#[cfg(test)]
mod tests {
    use super::functions;

    #[test]
    fn inspector_authoring_matches_embedded_functions_and_registry_seeds() {
        let source = include_str!("../../../language/lcnf-1.2/tooling/src/Extract.lex.tex");
        let body = source
            .split_once("\\begin{toolingmodule}\n")
            .unwrap()
            .1
            .split_once("\\end{toolingmodule}")
            .unwrap()
            .0;
        let embedded = lexlean::surface::tooling::parse_module(body, "lexlean/tooling-module/1")
            .expect("closed tooling notation");
        let embedded: serde_json::Value =
            serde_json::from_str(&embedded.to_canonical_string()).unwrap();
        let declarations = embedded["declarations"].as_array().unwrap();
        let authored = functions();
        assert_eq!(authored.len(), 15);
        for function in &authored {
            let actual = declarations
                .iter()
                .find(|row| row["name"] == function["name"])
                .expect("every authored inspector is embedded");
            assert_eq!(actual, function, "{}", function["name"]);
        }
        let seeds = crate::lcnf_registry::seeds();
        for required in [
            "call:Nat.sub",
            "call:Nat.log2",
            "call:String.utf8ByteSize",
            "call:Lean.ConstantInfo.levelParams",
            "inductive:Lean.BinderInfo",
            "inductive:Lean.Level",
            "inductive:Lean.Literal",
        ] {
            assert!(seeds.iter().any(|seed| seed == required), "{required}");
        }
    }
}
